PROTECTED (Hex Encoded)
local hex_data = [[]]

-- Decode Hex to String
local function hex_to_str(s)
    local out = {}
    for i = 1, #s, 2 do
        local byte = tonumber(s:sub(i, i+1), 16)
        out[#out + 1] = string.char(byte)
    end
    return table.concat(out)
end

-- I-decode at i-run
local decoded_script = hex_to_str(hex_data)
local func, err = loadstring(decoded_script)

if func then
    local success, exec_err = pcall(func)
    if not success then
        warn("Protected Script Error: " .. tostring(exec_err))
    end
else
    warn("Failed to load protected script: " .. tostring(err))
end
